class SecretVault:
    def __init__(self):
        self._secrets = {}

    def set_secret(self, name, value):
        versions = self._secrets.setdefault(name, [])
        version = f'v{len(versions) + 1}'
        versions.append((version, value))
        return version

    def get_secret(self, name, version=None):
        versions = self._secrets.get(name)
        if not versions:
            raise KeyError(name)
        if version is None:
            ver, value = versions[-1]
            return value, ver
        for ver, value in versions:
            if ver == version:
                return value, ver
        raise KeyError(f'{name} {version}')

vault = SecretVault()
v1 = vault.set_secret('db-password', 'hunter2')
print(f'set db-password -> {v1}')
v2 = vault.set_secret('db-password', 'hunter3')
print(f'set db-password -> {v2}')
value, ver = vault.get_secret('db-password')
print(f'get db-password -> {value} ({ver})')
value, ver = vault.get_secret('db-password', 'v1')
print(f'get db-password v1 -> {value} ({ver})')
